def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    out = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        token = "\\" + c if c == "\\" or "0" <= c <= "9" else c
        if run_len >= 3:
            out.append(str(run_len))
            out.append(token)
        else:
            out.append(token * run_len)
        i = j
    return "".join(out)
